import React, { useState } from 'react';
import styled from 'styled-components';

const ContactSection = styled.section`
  padding: 140px 0 100px;
  background: #FAF8F5;
  text-align: center;
`;

const ContactContainer = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
`;

const ContactHeader = styled.div`
  margin-bottom: 4rem;

  h1 {
    font-size: clamp(2.5rem, 5vw, 4rem);
    font-weight: 800;
    margin: 1.5rem 0 2rem;
    color: #000000;
    letter-spacing: -0.02em;
    line-height: 1.1;

    span {
      color: #F5BF42;
    }
  }

  p {
    font-size: 1.25rem;
    color: #6B7280;
    line-height: 1.6;
  }
`;

const ContactBadge = styled.span`
  display: inline-block;
  background: #F5BF42;
  color: #000;
  padding: 8px 20px;
  border-radius: 25px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  margin-bottom: 2rem;
`;

const ContactContent = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  text-align: left;

  @media (max-width: 968px) {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
`;

const ContactInfo = styled.div`
  h3 {
    font-size: 1.5rem;
    font-weight: 700;
    color: #000000;
    margin-bottom: 2rem;
  }
`;

const ContactItem = styled.div`
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 2rem;
`;

const ContactIcon = styled.div`
  width: 50px;
  height: 50px;
  background: linear-gradient(135deg, #F5BF42 0%, #E6A835 100%);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
`;

const ContactDetails = styled.div`
  h4 {
    font-weight: 600;
    color: #000000;
    margin-bottom: 0.5rem;
    font-size: 1rem;
  }

  p {
    color: #6B7280;
    margin: 0;
    font-size: 0.875rem;
    line-height: 1.4;
  }
`;

const ContactForm = styled.div`
  background: #FFFFFF;
  border-radius: 20px;
  padding: 2.5rem;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);

  h3 {
    font-size: 1.5rem;
    font-weight: 700;
    color: #000000;
    margin-bottom: 0.5rem;
  }

  .form-subtitle {
    color: #6B7280;
    margin-bottom: 2rem;
    font-size: 0.875rem;
  }
`;

const FormRow = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.5rem;

  @media (max-width: 600px) {
    grid-template-columns: 1fr;
  }
`;

const FormGroup = styled.div`
  label {
    display: block;
    color: #374151;
    font-size: 0.875rem;
    font-weight: 500;
    margin-bottom: 0.5rem;
  }
`;

const FormInput = styled.input`
  width: 100%;
  padding: 12px 16px;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  font-size: 0.875rem;
  transition: all 0.3s ease;
  box-sizing: border-box;

  &:focus {
    outline: none;
    border-color: #F5BF42;
    box-shadow: 0 0 0 3px rgba(245, 191, 66, 0.1);
  }

  &::placeholder {
    color: #9CA3AF;
  }
  
  @media (max-width: 768px) {
    padding: 16px;
    font-size: 1rem;
    min-height: 48px;
  }
`;

const FormTextarea = styled.textarea`
  width: 100%;
  padding: 12px 16px;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  font-size: 0.875rem;
  min-height: 120px;
  resize: vertical;
  font-family: inherit;
  transition: all 0.3s ease;
  box-sizing: border-box;

  &:focus {
    outline: none;
    border-color: #F5BF42;
    box-shadow: 0 0 0 3px rgba(245, 191, 66, 0.1);
  }

  &::placeholder {
    color: #9CA3AF;
  }
  
  @media (max-width: 768px) {
    padding: 16px;
    font-size: 1rem;
    min-height: 100px;
  }
`;

const SubmitButton = styled.button`
  width: 100%;
  padding: 15px 24px;
  background: linear-gradient(135deg, #F5BF42 0%, #E6A835 100%);
  color: #000000;
  border: none;
  border-radius: 10px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(245, 191, 66, 0.3);
    background: linear-gradient(135deg, #E6A835 0%, #D4941E 100%);
  }

  &:disabled {
    opacity: 0.7;
    cursor: not-allowed;
    transform: none;
  }
  
  @media (max-width: 768px) {
    padding: 18px 24px;
    font-size: 1.1rem;
    min-height: 52px;
    
    &:hover {
      transform: none; /* Reduce transforms on mobile for better performance */
    }
  }
`;

const Contact: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    company: '',
    message: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    
    // Simulate form submission
    setTimeout(() => {
      setIsSubmitting(false);
      alert('Message sent successfully! We\'ll get back to you within 24 hours.');
      setFormData({ name: '', email: '', company: '', message: '' });
    }, 2000);
  };

  return (
    <ContactSection>
      <ContactContainer>
        <ContactHeader>
          <ContactBadge>CONTACT</ContactBadge>
          <h1>
            Let's <span>talk</span>
          </h1>
          <p>Have questions? We're here to help you get started.</p>
        </ContactHeader>
        
        <ContactContent>
          <ContactInfo>
            <h3>How to reach us</h3>
            
            <ContactItem>
              <ContactIcon>✉️</ContactIcon>
              <ContactDetails>
                <h4>Email</h4>
                <p>hello@aicallassist.com</p>
                <p>We respond within 24 hours</p>
              </ContactDetails>
            </ContactItem>
            
            <ContactItem>
              <ContactIcon>📞</ContactIcon>
              <ContactDetails>
                <h4>Phone</h4>
                <p>+1 (555) 123-4567</p>
                <p>Mon-Fri, 9:00 - 18:00 EST</p>
              </ContactDetails>
            </ContactItem>
            
            <ContactItem>
              <ContactIcon>📍</ContactIcon>
              <ContactDetails>
                <h4>Address</h4>
                <p>San Francisco, USA</p>
                <p>123 Innovation Street, 94105</p>
              </ContactDetails>
            </ContactItem>
            
            <ContactItem>
              <ContactIcon>⚡</ContactIcon>
              <ContactDetails>
                <h4>Quick Response Guaranteed</h4>
                <p>Our team responds within 2-4 hours during business hours. For urgent requests, please use our phone number.</p>
              </ContactDetails>
            </ContactItem>
          </ContactInfo>
          
          <ContactForm>
            <h3>Send Message</h3>
            <p className="form-subtitle">We'll get back to you as soon as possible</p>
            
            <form onSubmit={handleSubmit}>
              <FormRow>
                <FormGroup>
                  <label htmlFor="name">Name</label>
                  <FormInput
                    type="text"
                    id="name"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    placeholder="Your Name"
                    required
                  />
                </FormGroup>
                
                <FormGroup>
                  <label htmlFor="email">Email</label>
                  <FormInput
                    type="email"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    placeholder="name@company.com"
                    required
                  />
                </FormGroup>
              </FormRow>
              
              <FormGroup style={{ marginBottom: '1.5rem' }}>
                <label htmlFor="company">Company (optional)</label>
                <FormInput
                  type="text"
                  id="company"
                  name="company"
                  value={formData.company}
                  onChange={handleChange}
                  placeholder="Company Name"
                />
              </FormGroup>
              
              <FormGroup style={{ marginBottom: '2rem' }}>
                <label htmlFor="message">Message</label>
                <FormTextarea
                  id="message"
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  placeholder="How can we help you?"
                  required
                />
              </FormGroup>
              
              <SubmitButton type="submit" disabled={isSubmitting}>
                {isSubmitting ? '⏳ Sending...' : '📩 Send Message'}
              </SubmitButton>
            </form>
          </ContactForm>
        </ContactContent>
      </ContactContainer>
    </ContactSection>
  );
};

export default Contact;