const Breakout = styled.div`
  width: 100vw;
  margin-left: calc(-50vw + 50%);
  margin-right: calc(-50vw + 50%);
  padding: 0 24px;
  margin-top: 3rem;
`;
const HeroSection = styled.section`
  padding: 140px 0 100px;
  background: #ffffff;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  overflow: hidden;
  
`;

const HeroContent = styled.div`
  position: relative;
  z-index: 1;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 20px;
  text-align: center;

  h1 {
    font-size: clamp(2rem, 8vw, 4.5rem);
    line-height: 1.1;
    font-weight: 800;
    margin-bottom: 2rem;
    color: #000000;
    letter-spacing: -0.02em;
  }

  .gradient-text {
    background: linear-gradient(135deg, #f59e0b 0%, #fbbf24 30%, #f59e0b 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    background-size: 200% 200%;
    animation: titleGradientFlow 5s ease-in-out infinite;
    position: relative;
    display: inline-block;
    
    &::before {
      content: '🚀';
      position: absolute;
      left: -3rem;
      top: 50%;
      transform: translateY(-50%);
      font-size: 2.5rem;
      opacity: 0.9;
      animation: rocketFloat 3s ease-in-out infinite;
    }
    
    &::after {
      content: '✨';
      position: absolute;
      right: -2.5rem;
      top: 20%;
      font-size: 1.8rem;
      opacity: 0.8;
      animation: sparkle 2s ease-in-out infinite;
    }

    @media (max-width: 768px) {
      &::before {
        left: -2rem;
        font-size: 2rem;
      }
      
      &::after {
        right: -1.5rem;
        font-size: 1.5rem;
      }
    }
  }
  
  @keyframes titleGradientFlow {
    0%, 100% {
      background-position: 0% 50%;
    }
    50% {
      background-position: 100% 50%;
    }
  }
  
  @keyframes rocketFloat {
    0%, 100% {
      transform: translateY(-50%) rotate(-5deg);
    }
    50% {
      transform: translateY(-60%) rotate(5deg);
    }
  }
  
  @keyframes sparkle {
    0%, 100% {
      transform: scale(1) rotate(0deg);
      opacity: 0.7;
    }
    50% {
      transform: scale(1.2) rotate(180deg);
      opacity: 1;
    }
  }

  p {
    font-size: clamp(1.125rem, 2vw, 1.375rem);
    line-height: 1.7;
    color: rgba(31, 41, 55, 0.8);
    margin-bottom: 3rem;
    max-width: 700px;
    margin-left: auto;
    margin-right: auto;
  }
`;

const CTAButtons = styled.div`
  display: flex;
  gap: 1.5rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
`;
const PlayIcon = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
    className="lucide lucide-play"
    style={{
      width: "1.25rem",
      height: "1.25rem",
      marginRight: "0.5rem",
      fill: "#F5B800",
      color: "#F5B800",
      flexShrink: 0,
      pointerEvents: "none",
    }}
  >
    <polygon points="6 3 20 12 6 21 6 3" />
  </svg>
);

const Button = styled(Link)<{ variant: 'primary' | 'secondary' }>`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  white-space: nowrap;

  height: 2.5rem;
  padding: 24px 32px;

  font-size: 1rem;
  font-weight: 600;
  border-radius: 9999px;
  text-decoration: none;

  transition: all 0.25s ease;
  cursor: pointer;

  border: 2px solid #e5e7eb;
  background: #ffffff;
  color: #0f0f0f;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);

  /* Icon styles */
  svg {
    width: 1.25rem;
    height: 1.25rem;
    flex-shrink: 0;
    pointer-events: none;
  }

  &:hover {
    background: #f9fafb;
    transform: translateY(-2px);
  }

  &:focus-visible {
    outline: none;
    box-shadow: 0 0 0 1px #0f0f0f;
  }

  &:disabled {
    pointer-events: none;
    opacity: 0.5;
  }

  ${({ variant }) =>
    variant === "primary" &&
    `
      background: #F5B800;
      color: #ffffff;
      border-color: transparent;

      svg {
        fill: #ffffff;
        stroke: #ffffff;
      }

      box-shadow: 0 10px 25px rgba(245, 184, 0, 0.25);

      &:hover {
        background: #D4A000;
        box-shadow: 0 14px 30px rgba(245, 184, 0, 0.35);
      }
    `}

  ${({ variant }) =>
    variant === "secondary" &&
    `
      background: #ffffff;
      color: #0f0f0f;
      border-color: #e5e7eb;
      padding: 24px 32px;

      svg {
        fill: #F5B800;
        stroke: #F5B800;
      }
    `}
`;


