/* CARD */
export const FeatureCard = styled.div`
  position: relative;
  padding: 2rem;
  border-radius: 1rem;
  background: #ffffff;
  border: 1px solid #f1f5f9;
  transition: all 0.3s ease;

  &:hover {
    border-color: rgba(245, 184, 0, 0.3);
    background: linear-gradient(to bottom, #fffbeb, #ffffff);
  }

  h3 {
    font-size: 1.25rem;
    font-weight: 600;
    color: #0f0f0f;
    margin-bottom: 0.75rem;
  }

  p {
    color: #6b7280;
    line-height: 1.6;
  }
`;

/* ICON */
export const FeatureIcon = styled.div`
  width: 56px;
  height: 56px;
  border-radius: 1rem;
  background: rgba(245, 184, 0, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  transition: all 0.3s ease;

  svg {
    width: 28px;
    height: 28px;
    color: #f5b800;
    transition: color 0.3s ease;
  }

  ${FeatureCard}:hover & {
    background: #f5b800;
    transform: scale(1.1);

    svg {
      color: #ffffff;
    }
  }
`;
