import React from 'react';
import styled from 'styled-components';
import { useAuth } from '../../contexts/AuthContext';

const DashboardContainer = styled.div`
  min-height: 100vh;
  padding: 140px 2rem 4rem;
  background: radial-gradient(ellipse at center, rgba(255, 255, 0, 0.05) 0%, rgba(255, 255, 255, 0) 50%);
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: 
      radial-gradient(circle at 25% 25%, rgba(255, 255, 0, 0.1) 0%, transparent 50%),
      radial-gradient(circle at 75% 75%, rgba(255, 255, 0, 0.05) 0%, transparent 50%);
    pointer-events: none;
    z-index: 0;
  }
`;

const DashboardContent = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
`;

const WelcomeSection = styled.section`
  text-align: center;
  margin-bottom: 4rem;
`;

const WelcomeTitle = styled.h1`
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  margin-bottom: 1rem;
  background: linear-gradient(135deg, #ffff00 0%, #ffd700 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
`;

const WelcomeSubtitle = styled.p`
  font-size: 1.125rem;
  color: #6b7280;
  margin-bottom: 2rem;
`;

const UserCard = styled.div`
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 0, 0.3);
  border-radius: 20px;
  padding: 2rem;
  margin-bottom: 3rem;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
`;

const UserInfo = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
`;

const InfoItem = styled.div`
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
`;

const InfoLabel = styled.span`
  font-size: 0.875rem;
  font-weight: 500;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.5px;
`;

const InfoValue = styled.span`
  font-size: 1.125rem;
  font-weight: 600;
  color: #1f2937;
`;

const ActionsSection = styled.section`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  margin-bottom: 4rem;
`;

const ActionCard = styled.div`
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(168, 218, 220, 0.4);
  border-radius: 20px;
  padding: 2rem;
  text-align: center;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  cursor: pointer;
  
  &:hover {
    transform: translateY(-4px);
    border-color: #a8dadc;
    box-shadow: 0 20px 40px rgba(168, 218, 220, 0.3);
  }
`;

const ActionIcon = styled.div`
  font-size: 3rem;
  margin-bottom: 1rem;
`;

const ActionTitle = styled.h3`
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: #1f2937;
`;

const ActionDescription = styled.p`
  font-size: 0.875rem;
  color: #6b7280;
  line-height: 1.5;
`;

const LogoutButton = styled.button`
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  color: #2D2D2D;
  border: none;
  padding: 12px 24px;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  
  &:hover {
    background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(239, 68, 68, 0.3);
  }
`;

const Dashboard: React.FC = () => {
  const { user, logout } = useAuth();

  const handleLogout = () => {
    logout();
  };

  if (!user) {
    return (
      <DashboardContainer>
        <DashboardContent>
          <div style={{ textAlign: 'center', padding: '4rem 0' }}>
            <div className="spinning">⏳</div>
            <p style={{ marginTop: '1rem', color: 'rgba(255, 255, 255, 0.6)' }}>
              Loading user information...
            </p>
          </div>
        </DashboardContent>
      </DashboardContainer>
    );
  }

  return (
    <DashboardContainer>
      <DashboardContent>
        <WelcomeSection>
          <WelcomeTitle>
            Welcome back, {user.profile.firstName}! 👋
          </WelcomeTitle>
          <WelcomeSubtitle>
            Your AI CallAssist dashboard is ready. Manage your appointments and settings below.
          </WelcomeSubtitle>
        </WelcomeSection>

        <UserCard>
          <h2 style={{ marginBottom: '1.5rem', color: '#1f2937' }}>Account Information</h2>
          <UserInfo>
            <InfoItem>
              <InfoLabel>Full Name</InfoLabel>
              <InfoValue>{user.profile.fullName}</InfoValue>
            </InfoItem>
            <InfoItem>
              <InfoLabel>Email Address</InfoLabel>
              <InfoValue>{user.email}</InfoValue>
            </InfoItem>
            <InfoItem>
              <InfoLabel>Phone Number</InfoLabel>
              <InfoValue>{user.profile.phone || 'Not provided'}</InfoValue>
            </InfoItem>
            <InfoItem>
              <InfoLabel>Account Status</InfoLabel>
              <InfoValue style={{ color: user.isActive ? '#22c55e' : '#ef4444' }}>
                {user.isActive ? 'Active' : 'Inactive'}
              </InfoValue>
            </InfoItem>
            <InfoItem>
              <InfoLabel>Email Verified</InfoLabel>
              <InfoValue style={{ color: user.isEmailVerified ? '#22c55e' : '#ff8c42' }}>
                {user.isEmailVerified ? '✅ Verified' : '⏳ Pending'}
              </InfoValue>
            </InfoItem>
            <InfoItem>
              <InfoLabel>Member Since</InfoLabel>
              <InfoValue>
                {new Date(user.createdAt).toLocaleDateString('en-US', {
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric'
                })}
              </InfoValue>
            </InfoItem>
          </UserInfo>
          <div style={{ textAlign: 'right' }}>
            <LogoutButton onClick={handleLogout}>
              🚪 Logout
            </LogoutButton>
          </div>
        </UserCard>

        <ActionsSection>
          <ActionCard onClick={() => window.location.href = '/'}>            <ActionIcon>📞</ActionIcon>
            <ActionTitle>Test AI Calls</ActionTitle>
            <ActionDescription>
              Try our AI calling feature and see how it handles appointment bookings
            </ActionDescription>
          </ActionCard>

          <ActionCard>
            <ActionIcon>📅</ActionIcon>
            <ActionTitle>Manage Appointments</ActionTitle>
            <ActionDescription>
              View, edit, and organize your upcoming appointments and bookings
            </ActionDescription>
          </ActionCard>

          <ActionCard>
            <ActionIcon>⚙️</ActionIcon>
            <ActionTitle>Account Settings</ActionTitle>
            <ActionDescription>
              Update your profile, notification preferences, and security settings
            </ActionDescription>
          </ActionCard>

          <ActionCard>
            <ActionIcon>📊</ActionIcon>
            <ActionTitle>Analytics</ActionTitle>
            <ActionDescription>
              View call statistics, appointment metrics, and performance insights
            </ActionDescription>
          </ActionCard>

          <ActionCard>
            <ActionIcon>🎧</ActionIcon>
            <ActionTitle>Support</ActionTitle>
            <ActionDescription>
              Get help, browse documentation, or contact our support team
            </ActionDescription>
          </ActionCard>

          <ActionCard>
            <ActionIcon>🔑</ActionIcon>
            <ActionTitle>API Keys</ActionTitle>
            <ActionDescription>
              Manage your VAPI credentials and integration settings
            </ActionDescription>
          </ActionCard>
        </ActionsSection>
      </DashboardContent>
    </DashboardContainer>
  );
};

export default Dashboard;