// VAPI Configuration and Service
export interface VapiCallRequest {
  assistantId: string;
  phoneNumberId: string;
  customer: {
    number: string;
    name?: string;
  };
  assistantOverrides?: {
    variableValues?: Record<string, string>;
  };
}

export interface VapiCallResponse {
  id: string;
  status: string;
  phoneNumber: string;
  assistantId: string;
  createdAt: string;
}

export const VAPI_CONFIG = {
  baseURL: 'https://api.vapi.ai',
  endpoints: {
    createCall: '/call/phone',
    getCall: '/call',
  },
  // Default timeout for API calls
  timeout: 30000,
};

export class VapiError extends Error {
  constructor(
    message: string,
    public _statusCode?: number,
    public _response?: any
  ) {
    super(message);
    this.name = 'VapiError';
  }
}

// Utility functions for phone number formatting
export const phoneUtils = {
  /**
   * Clean and format phone number for international calling
   */
  formatForVapi: (phone: string): string => {
    // Remove all non-numeric characters except +
    const cleaned = phone.replace(/[^\d\+]/g, '');
    
    // If it doesn't start with +, assume US number
    if (!cleaned.startsWith('+')) {
      return `+1${cleaned}`;
    }
    
    return cleaned;
  },

  /**
   * Validate phone number format
   */
  isValid: (phone: string): boolean => {
    const cleaned = phone.replace(/[\s\-\(\)]/g, '');
    const phoneRegex = /^[\+]?[1-9][\d]{0,15}$/;
    return phoneRegex.test(cleaned) && cleaned.length >= 10;
  },

  /**
   * Format phone number for display
   */
  formatForDisplay: (phone: string): string => {
    const cleaned = phone.replace(/\D/g, '');
    
    if (cleaned.length === 11 && cleaned.startsWith('1')) {
      const area = cleaned.slice(1, 4);
      const first = cleaned.slice(4, 7);
      const second = cleaned.slice(7);
      return `+1 (${area}) ${first}-${second}`;
    }
    
    if (cleaned.length === 10) {
      const area = cleaned.slice(0, 3);
      const first = cleaned.slice(3, 6);
      const second = cleaned.slice(6);
      return `+1 (${area}) ${first}-${second}`;
    }
    
    return phone;
  }
};

/**
 * VAPI Service for handling API calls
 */
export class VapiService {
  private apiKey: string;
  private baseURL: string;

  constructor(apiKey: string, baseURL: string = VAPI_CONFIG.baseURL) {
    this.apiKey = apiKey;
    this.baseURL = baseURL;
  }

  /**
   * Create a phone call using VAPI
   */
  async createCall(request: VapiCallRequest): Promise<VapiCallResponse> {
    try {
      const response = await fetch(`${this.baseURL}${VAPI_CONFIG.endpoints.createCall}`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${this.apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(request),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new VapiError(
          data.message || 'Failed to create call',
          response.status,
          data
        );
      }

      return data;
    } catch (error) {
      if (error instanceof VapiError) {
        throw error;
      }
      
      throw new VapiError(
        error instanceof Error ? error.message : 'Network error occurred'
      );
    }
  }

  /**
   * Get call status
   */
  async getCall(callId: string): Promise<VapiCallResponse> {
    try {
      const response = await fetch(`${this.baseURL}${VAPI_CONFIG.endpoints.getCall}/${callId}`, {
        headers: {
          'Authorization': `Bearer ${this.apiKey}`,
        },
      });

      const data = await response.json();

      if (!response.ok) {
        throw new VapiError(
          data.message || 'Failed to get call status',
          response.status,
          data
        );
      }

      return data;
    } catch (error) {
      if (error instanceof VapiError) {
        throw error;
      }
      
      throw new VapiError(
        error instanceof Error ? error.message : 'Network error occurred'
      );
    }
  }
}

export default VapiService;