import React from 'react';
import styled from 'styled-components';
import { Link } from 'react-router-dom';

/* =====================
   STYLES
===================== */

const FooterContainer = styled.footer`
  background: #0f0f0f;
  color: #ffffff;
  padding: 6rem 0 3rem;
`;

const Inner = styled.div`
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
`;

const TopGrid = styled.div`
  display: grid;
  grid-template-columns: 1.2fr repeat(3, 1fr);
  gap: 4rem;
  margin-bottom: 3rem;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
`;

const Brand = styled.div`
  display: flex;
  flex-direction: column;
  gap: 1rem;
`;

const LogoRow = styled.div`
  display: flex;
  align-items: center;
  gap: 0.75rem;
`;

const LogoIcon = styled.div`
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: #f5b800;
  display: flex;
  align-items: center;
  justify-content: center;
`;

const BrandName = styled.div`
  font-size: 1.25rem;
  font-weight: 800;

  span {
    color: #f5b800;
  }
`;

const BrandText = styled.p`
  color: #6b7280;
  font-size: 0.875rem;
  line-height: 1.6;
  max-width: 280px;
`;

const Column = styled.div``;

const ColumnTitle = styled.h4`
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
`;

const LinkList = styled.ul`
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
`;

const FooterLink = styled(Link)`
  color: #6b7280;
  font-size: 0.875rem;
  text-decoration: none;
  transition: color 0.2s ease;

  &:hover {
    color: #f5b800;
  }
`;

const FooterAnchor = styled.a`
  color: #6b7280;
  font-size: 0.875rem;
  text-decoration: none;
  transition: color 0.2s ease;

  &:hover {
    color: #f5b800;
  }
`;

const BottomBar = styled.div`
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;

  @media (max-width: 768px) {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
`;

const Copyright = styled.p`
  color: #6b7280;
  font-size: 0.875rem;
`;

/* =====================
   COMPONENT
===================== */

const Footer: React.FC = () => {
  return (
    <FooterContainer>
      <Inner>

        {/* TOP */}
        <TopGrid>
          {/* BRAND */}
          <Brand>
            <LogoRow>
              <LogoIcon>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2">
                  <path d="M9.937 15.5A2 2 0 0 0 8.5 14.063l-6.135-1.582a.5.5 0 0 1 0-.962L8.5 9.936A2 2 0 0 0 9.937 8.5l1.582-6.135a.5.5 0 0 1 .963 0L14.063 8.5A2 2 0 0 0 15.5 9.937l6.135 1.581a.5.5 0 0 1 0 .964L15.5 14.063a2 2 0 0 0-1.437 1.437l-1.582 6.135a.5.5 0 0 1-.963 0z"/>
                </svg>
              </LogoIcon>

              <BrandName>
                Nova<span>AI</span>
              </BrandName>
            </LogoRow>

            <BrandText>
              Die intelligente AI-Lösung für moderne Unternehmen.
            </BrandText>
          </Brand>

          {/* PRODUCT */}
          <Column>
            <ColumnTitle>Produkt</ColumnTitle>
            <LinkList>
              <li><FooterLink to="/features">Features</FooterLink></li>
              <li><FooterLink to="/pricing">Preise</FooterLink></li>
              <li><FooterAnchor href="#">API</FooterAnchor></li>
            </LinkList>
          </Column>

          {/* COMPANY */}
          <Column>
            <ColumnTitle>Unternehmen</ColumnTitle>
            <LinkList>
              <li><FooterLink to="/about">Über uns</FooterLink></li>
              <li><FooterAnchor href="#">Karriere</FooterAnchor></li>
              <li><FooterLink to="/contact">Kontakt</FooterLink></li>
            </LinkList>
          </Column>

          {/* LEGAL */}
          <Column>
            <ColumnTitle>Rechtliches</ColumnTitle>
            <LinkList>
              <li><FooterAnchor href="#">Datenschutz</FooterAnchor></li>
              <li><FooterAnchor href="#">AGB</FooterAnchor></li>
              <li><FooterAnchor href="#">Impressum</FooterAnchor></li>
            </LinkList>
          </Column>
        </TopGrid>

        {/* BOTTOM */}
        <BottomBar>
          <Copyright>
            © 2026 NovaAI. Alle Rechte vorbehalten.
          </Copyright>
        </BottomBar>

      </Inner>
    </FooterContainer>
  );
};

export default Footer;
